css:
@import url("https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&display=swap");
:root{--teal:#0F766E;--teal-2:#14B8A6;--teal-l:#E6F6F4;--amber:#F59E0B;--rose:#E11D48;--ink:#172033;--text:#253045;--muted:#667085;--line:#E6E9EF;--bg:#F5F7FA;--card:#fff;
--font:"Outfit",system-ui,-apple-system,"Segoe UI",sans-serif}
*,*::before,*::after{box-sizing:border-box}
body{margin:0;font-family:var(--font);font-size:16px;line-height:1.5;color:var(--text);background:var(--bg);-webkit-font-smoothing:antialiased}
a{color:inherit}img{display:block;max-width:100%}
h1,h2,h3{margin:0;color:var(--ink);letter-spacing:-.01em}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--amber);padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--teal-2);outline-offset:2px;border-radius:6px}
.app{display:grid;grid-template-columns:248px 1fr;min-height:100vh}
.side{background:var(--ink);color:#AAB4C5;padding:22px 16px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column}
.brand{display:flex;align-items:center;gap:10px;color:#fff;font-weight:800;font-size:21px;padding:0 8px 22px;text-decoration:none}
.brand i{width:30px;height:30px;border-radius:9px;background:var(--teal-2);display:grid;place-items:center}.brand i::after{content:"";width:12px;height:12px;border-radius:50%;border:3px solid var(--ink)}
.nav-l{list-style:none;padding:0;margin:0}
.nav-l b{display:block;font-size:12px;letter-spacing:.06em;color:#6D788C;margin:18px 10px 8px}
.nav-l a{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:10px;text-decoration:none;font-weight:500}
.nav-l a:hover{background:#222D44;color:#fff}.nav-l a.on{background:var(--teal);color:#fff}
.nav-l svg{width:18px;height:18px}
.side .site{margin-top:auto;background:#222D44;border-radius:12px;padding:14px;font-size:14px}
.side .site b{color:#fff;display:block}
.main{min-width:0}
.top{display:flex;align-items:center;gap:16px;padding:18px 28px;background:var(--card);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:10}
.menu-btn{display:none;background:none;border:1px solid var(--line);border-radius:10px;padding:8px 10px;cursor:pointer}
.search{flex:1;max-width:420px;display:flex;align-items:center;gap:10px;background:var(--bg);border:1px solid var(--line);border-radius:12px;padding:9px 14px;color:var(--muted)}
.search input{border:0;background:transparent;font:inherit;width:100%;color:var(--text)}.search input:focus{outline:none}
.range{display:flex;background:var(--bg);border:1px solid var(--line);border-radius:12px;padding:3px;margin-left:auto}
.range button{border:0;background:none;font:inherit;font-weight:600;font-size:14px;padding:7px 14px;border-radius:9px;cursor:pointer;color:var(--muted)}
.range button[aria-pressed="true"]{background:#fff;color:var(--ink);box-shadow:0 1px 3px rgba(0,0,0,.1)}
.me{display:flex;align-items:center;gap:10px;font-weight:600;font-size:14px}.me img{width:36px;height:36px;border-radius:50%;object-fit:cover}
.content{padding:26px 28px 40px}
.title{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:22px;flex-wrap:wrap}
.title h1{font-size:28px;font-weight:800}.title p{margin:4px 0 0;color:var(--muted)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border-radius:10px;font-weight:600;font-size:14px;text-decoration:none;border:1px solid var(--line);background:#fff;cursor:pointer;font-family:var(--font);color:var(--ink)}
.btn.pri{background:var(--teal);color:#fff;border-color:var(--teal)}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:16px}
.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px}
.kpi small{color:var(--muted);font-weight:500;font-size:14px}
.kpi .v{font-size:30px;font-weight:800;color:var(--ink);margin:4px 0 2px}
.kpi .d{font-size:13px;font-weight:600}.up{color:#059669}.down{color:var(--rose)}
.kpi svg{width:100%;height:36px;margin-top:8px}
.row{display:grid;grid-template-columns:2fr 1fr;gap:16px;margin-bottom:16px}
.row3{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:16px}
.card h2{font-size:17px;font-weight:700}
.card-h{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;gap:10px}
.legend{display:flex;gap:16px;font-size:13px;color:var(--muted)}.legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:6px}
#line{width:100%;height:260px}
.bars .b{margin-bottom:12px}.bars .lab{display:flex;justify-content:space-between;font-size:14px;margin-bottom:5px}.bars .lab b{font-weight:600}
.bars .track{height:9px;background:var(--bg);border-radius:6px;overflow:hidden}.bars .track i{display:block;height:100%;border-radius:6px;background:var(--teal-2)}
.donut{display:flex;align-items:center;gap:18px}
.donut svg{width:150px;height:150px;flex:none}
.donut ul{list-style:none;padding:0;margin:0;font-size:14px;flex:1}.donut li{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--line)}
.donut li i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:8px}
table{width:100%;border-collapse:collapse;font-size:14px}
th{text-align:left;color:var(--muted);font-weight:500;padding:8px 0;border-bottom:1px solid var(--line)}
td{padding:11px 0;border-bottom:1px solid var(--line)}td:not(:first-child),th:not(:first-child){text-align:right}
td a{text-decoration:none;font-weight:500}
.live{display:flex;align-items:center;gap:8px;font-size:13px;color:#059669;font-weight:600}.live i{width:8px;height:8px;border-radius:50%;background:#10B981;animation:p 1.6s infinite}
@keyframes p{50%{opacity:.3}}@media (prefers-reduced-motion:reduce){.live i{animation:none}}
.bignum{font-size:46px;font-weight:800;color:var(--ink);line-height:1;margin:6px 0 12px}
.mini-bars{display:flex;gap:4px;align-items:flex-end;height:60px}.mini-bars i{flex:1;background:var(--teal-l);border-radius:3px}.mini-bars i:nth-last-child(-n+3){background:var(--teal-2)}
.foot{color:var(--muted);font-size:13px;margin-top:24px;text-align:center}
.foot a{color:var(--teal)}
@media (max-width:1100px){.kpis{grid-template-columns:1fr 1fr}.row,.row3{grid-template-columns:1fr}}
@media (max-width:860px){.app{grid-template-columns:1fr}.side{position:fixed;left:0;top:0;width:260px;z-index:30;transform:translateX(-100%);transition:transform .25s}.side.open{transform:none}
.menu-btn{display:block}.me span{display:none}.search{display:none}}
@media (max-width:520px){.kpis{grid-template-columns:1fr}.content{padding:20px 16px}.top{padding:14px 16px}.donut{flex-direction:column}}

javascript:
const R={7:{mult:.24,label:"Last 7 days compared with the 7 days before",days:7},30:{mult:1,label:"Last 30 days compared with the 30 days before",days:30},90:{mult:3.1,label:"Last 90 days compared with the 90 days before",days:90}};
const fmt=n=>n>=1000?(n/1000).toFixed(n>=10000?0:1)+'k':Math.round(n)+'';
function series(n,base,seed){const a=[];for(let i=0;i<n;i++){a.push(base+Math.sin(i*.55+seed)*base*.18+Math.cos(i*1.3+seed)*base*.08+i*base*.006)}return a}
function spark(vals,col){const mx=Math.max(...vals),mn=Math.min(...vals),w=200,h=36;const p=vals.map((v,i)=>`${(i/(vals.length-1)*w).toFixed(1)},${(h-(v-mn)/(mx-mn||1)*(h-4)-2).toFixed(1)}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true"><polyline points="${p}" fill="none" stroke="${col}" stroke-width="2"/></svg>`}
function render(r){const c=R[r];document.getElementById('sub').textContent=c.label;
 const k=[["Visitors",48210*c.mult,"+12.4%",1],["Page views",162900*c.mult,"+8.1%",1],["Bounce rate","38.2%","−2.3 pts",1],["Avg. visit time","3m 41s","−0.4%",0]];
 document.getElementById('kpis').innerHTML=k.map((x,i)=>`<div class="card kpi"><small>${x[0]}</small><div class="v">${typeof x[1]==='number'?fmt(x[1]):x[1]}</div><span class="d ${x[3]?'up':'down'}">${x[2]} vs previous</span>${spark(series(20,50,i+1),x[3]?'#14B8A6':'#E11D48')}</div>`).join('');
 const cur=series(c.days,1600*c.mult/ (c.days/30),1),prev=series(c.days,1400*c.mult/(c.days/30),2.4);
 const svg=document.getElementById('line'),W=svg.clientWidth||700,H=260,pl=40,pb=24,mx=Math.max(...cur,...prev)*1.1;
 const X=i=>pl+i/(c.days-1)*(W-pl-10),Y=v=>H-pb-(v/mx)*(H-pb-10);
 let g='';for(let j=0;j<=4;j++){const v=mx/4*j,y=Y(v);g+=`<line x1="${pl}" x2="${W-10}" y1="${y}" y2="${y}" stroke="#E6E9EF"/><text x="${pl-8}" y="${y+4}" text-anchor="end" font-size="11" fill="#667085">${fmt(v)}</text>`}
 const path=a=>a.map((v,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1)).join(' ');
 g+=`<path d="${path(cur)} L${X(c.days-1)} ${H-pb} L${pl} ${H-pb}Z" fill="#14B8A6" opacity=".1"/><path d="${path(prev)}" fill="none" stroke="#CBD5E1" stroke-width="2" stroke-dasharray="4 4"/><path d="${path(cur)}" fill="none" stroke="#14B8A6" stroke-width="3"/>`;
 svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML=g;
 const src=[["Google search",46],["Direct",21],["Instagram",13],["Email newsletter",11],["Referrals",9]];
 document.getElementById('sources').innerHTML=src.map(s=>`<div class="b"><div class="lab"><b>${s[0]}</b><span>${fmt(48210*c.mult*s[1]/100)} · ${s[1]}%</span></div><div class="track"><i style="width:${s[1]*2}%"></i></div></div>`).join('');
 const pages=[["/",38400],["/sofas",21700],["/sale",15300],["/blog/small-living-rooms",9800],["/delivery",6100]];
 document.getElementById('pages').innerHTML=pages.map((p,i)=>`<tr><td><a href="#">${p[0]}</a></td><td>${fmt(p[1]*c.mult)}</td><td>${['1m 12s','3m 05s','2m 40s','4m 22s','0m 58s'][i]}</td></tr>`).join('');
 const ctry=[["United States",41],["United Kingdom",18],["Canada",12],["Germany",9],["Australia",7]];
 document.getElementById('countries').innerHTML=ctry.map(s=>`<div class="b"><div class="lab"><b>${s[0]}</b><span>${s[1]}%</span></div><div class="track"><i style="width:${s[1]*2.2}%;background:#0F766E"></i></div></div>`).join('')}
const dev=[["Mobile",58,"#14B8A6"],["Desktop",34,"#0F766E"],["Tablet",8,"#F59E0B"]];let off=25,d='<circle cx="21" cy="21" r="15.9" fill="none" stroke="#F5F7FA" stroke-width="6"/>';
dev.forEach(x=>{d+=`<circle cx="21" cy="21" r="15.9" fill="none" stroke="${x[2]}" stroke-width="6" stroke-dasharray="${x[1]} ${100-x[1]}" stroke-dashoffset="${off}"/>`;off-=x[1]});
d+='<text x="21" y="22.5" text-anchor="middle" font-size="6" font-weight="800" fill="#172033">58%</text><text x="21" y="27" text-anchor="middle" font-size="2.6" fill="#667085">mobile</text>';
document.getElementById('donut').innerHTML=d;document.getElementById('devlist').innerHTML=dev.map(x=>`<li><span><i style="background:${x[2]}"></i>${x[0]}</span><b>${x[1]}%</b></li>`).join('');
document.getElementById('mini').innerHTML=Array.from({length:24},(_,i)=>`<i style="height:${30+Math.abs(Math.sin(i*.7))*70}%"></i>`).join('');
document.querySelectorAll('.range button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.range button').forEach(x=>x.setAttribute('aria-pressed',x===b));render(b.dataset.r)}));
render(30);window.addEventListener('resize',()=>render(document.querySelector('.range [aria-pressed=true]').dataset.r));
setInterval(()=>{const n=document.getElementById('now');n.textContent=Math.max(90,+n.textContent+Math.round(Math.random()*10-5))},3000);
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
